using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_e0a24e43062b4219ae737418e4b1250a.Client;

/// <summary>
/// Client-side AuthenticationStateProvider that reads persisted auth state
/// from PersistentComponentState (serialized by the server during prerendering).
/// </summary>
public class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticatedTask =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userInfo.Name),
                new(ClaimTypes.Email, userInfo.Name),
            };

            foreach (var role in userInfo.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, authenticationType: "PersistentAuth");
            var user = new ClaimsPrincipal(identity);
            _authStateTask = Task.FromResult(new AuthenticationState(user));
        }
        else
        {
            _authStateTask = _unauthenticatedTask;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authStateTask;
}

/// <summary>
/// Serializable model matching the server's UserInfo for deserialization.
/// </summary>
public class UserInfo
{
    public string Name { get; set; } = "";
    public string[] Roles { get; set; } = [];
}

